function streakInfo(nameLower,today){const {dayMeter}=computeCredits(logs),prefix=nameLower+'|',days=new Set();dayMeter.forEach((pts,key)=>{if(pts>=1&&key.startsWith(prefix))days.add(key.slice(prefix.length))});const step=(d,n)=>{const x=parseDateOnly(String(d||'').slice(0,10));if(!x)return'';x.setDate(x.getDate()+n);return localDate(x)};const now=String(today||'').slice(0,10),anchor=days.has(now)?now:days.has(step(now,-1))?step(now,-1):'';let current=0,d=anchor;while(d&&days.has(d)){current++;d=step(d,-1)}let best=0;for(const day of days){if(days.has(step(day,-1)))continue;let run=0,cur=day;while(days.has(cur)){run++;cur=step(cur,1)}if(run>best)best=run}return{current,best}}
