function momentumCurve(nameLower,today){const now=String(today||'').slice(0,10),key=String(nameLower||'').toLowerCase();if(!parseDateOnly(config.startDate)||!parseDateOnly(config.tripDate)||!parseDateOnly(now)||config.startDate>config.tripDate||now<config.startDate)return[];const {dayTotal}=computeCredits(logs),last=now<config.tripDate?now:config.tripDate,days=[];let d=config.startDate;while(d<=last){let points=0;const start=windowStart(d);dayTotal.forEach((value,dayKey)=>{const cut=dayKey.lastIndexOf('|'),name=dayKey.slice(0,cut),date=dayKey.slice(cut+1);if(date>=start&&date<=d&&(!key||name===key))points+=value});days.push({date:d,label:fmtDay(d),points});const next=parseDateOnly(d);next.setDate(next.getDate()+1);d=localDate(next)}return days}
