async function loadRemote(force=false){if(!endpoint)return false;const serial=++requestSerial;syncState='loading';syncDetail='';renderSync();try{const response=await fetchShared(endpoint);if(!response.ok)throw Error('network');const remote=unpackRemote(await response.json());if(serial!==requestSerial)return false;logs=remote.activities;if(remote.config)config=remote.config;configErrors=remote.configErrors;protocolVersion=remote.version;serverDate=remote.serverDate;challengeTimeZone=remote.timeZone;lastSyncedAt=Date.now();syncState='live';syncErrorCode='';persistShared();render();if(!participant(me))openIdentity(false);maybeShowWeekReview();return true}catch(error){if(serial!==requestSerial)return false;syncState=lastSyncedAt?'stale':'error';syncErrorCode=syncFailureCode(error);syncDetail=error.message==='version'?'Apps Script update required':'Could not reach the Sheet';renderSync();if(force)toast(syncDetail);return false}}
function renderSync(){if(typeof document==='undefined')return;const el=document.querySelector('#syncStatus');if(!el)return;if(!endpoint){el.textContent='Local mode';el.disabled=true;document.querySelector('#diagnosticTitle').textContent='Local mode';document.querySelector('#diagnosticDetail').textContent='Entries stay in this browser.';return}el.disabled=false;const age=lastSyncedAt?Math.floor((Date.now()-lastSyncedAt)/60000):null,when=age===null?'never':age<1?'just now':`${age}m ago`;el.textContent=syncState==='loading'?'Syncing…':syncState==='live'?`Live · ${when} · ↻`:syncState==='stale'?`Cached · retry ↻`:'Sync failed · retry ↻';document.querySelector('#diagnosticTitle').textContent=syncState==='live'?'Shared Sheet connected':syncDetail||'Using cached data';document.querySelector('#diagnosticDetail').textContent=`Protocol ${protocolVersion?'v'+protocolVersion:'not confirmed'} · Last successful sync: ${lastSyncedAt?new Date(lastSyncedAt).toLocaleString():'never'}.`+(challengeTimeZone?` Challenge day: ${challengeToday()} · ${challengeTimeZone}.`:'')+` This build expects v${[...SUPPORTED_API_VERSIONS][0]}.`;const code=document.querySelector('#diagnosticCode');code.classList.toggle('hide',!syncErrorCode);code.textContent=syncErrorCode}
async function submitActivity(event){event.preventDefault();if(saving)return;const target=currentTarget(),draft=draftActivity(),type=draft.type;if(!target)return openIdentity(false);if(!dateInChallenge(draft.date))return toast(`Choose a date from ${config.startDate} through ${config.tripDate}.`);if(type==='bounty'){if(!draft.bountyId)return toast('Choose one of today’s bounties.');if(!dailyBounties(draft.date).some(b=>b.id===draft.bountyId))return toast('That bounty is not available on that date.')}const button=document.querySelector('#saveActivityBtn');saving=true;button.disabled=true;button.textContent='Saving…';updateRecordPreview();let refreshFailed=false,storageFailed=false;try{if(endpoint){const response=await fetchShared(endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({name:draft.name,type:draft.type,date:draft.date,hardestGrade:draft.hardestGrade||'',note:draft.note||'',bountyId:draft.bountyId||''})});if(!response.ok)throw Error('Request failed.');const saved=await response.json();if(!saved||saved.ok!==true)throw Error(saved?.error?.message||'The Sheet rejected this entry.');refreshFailed=!(await loadRemote())}else{draft.id=`local-${Date.now()}`;draft.points=activityPoints(draft);draft.category=type==='bounty'?draft.category:type;logs=logs.concat([draft]);storageFailed=!persistLocal()}recordingFor=me;const noteField=document.querySelector('#activityNote');if(noteField)noteField.value='';const bountyField=document.querySelector('#bountySelect');if(bountyField)bountyField.value='';const gradeField=document.querySelector('#hardestGrade');if(gradeField)gradeField.value='';setDefaultRecordDate();document.querySelector('#dateFields').classList.add('hide');const dateToggleEl=document.querySelector('#dateToggle');dateToggleEl.setAttribute('aria-expanded','false');dateToggleEl.textContent='＋ Different day';render();showTab('you');const savedForOther=String(draft.name).toLowerCase()!==String(me).toLowerCase();toast(storageFailed?'Saved on this device only — storage is full.':refreshFailed?'Saved to the Sheet, but refresh failed. Do not retry the save; select sync to refresh.':savedForOther?`Saved for ${draft.name}.`:'Activity saved.')}catch(error){toast(`Save failed—${error.message||'the entry was not added.'} It is safe to retry.`)}finally{saving=false;button.disabled=false;button.textContent='Save activity';updateRecordPreview()}}
let pendingDelete=null,confirmAction=null;
function askConfirm(title,message,action,okLabel,note){confirmAction=action;const t=document.querySelector('#confirmTitle');if(t)t.textContent=title;const b=document.querySelector('#confirmBody');if(b)b.textContent=message;const ok=document.querySelector('#confirmOk');if(ok)ok.textContent=okLabel;const n=document.querySelector('#confirmNote');if(n){n.textContent=note||'';n.classList.toggle('hide',!note)}openModal('confirmModal')}
function confirmProceed(){const action=confirmAction;confirmAction=null;if(action)action()}
function feedSelector(feed){return feed==='personal'?'#personalActivity':'#activityList'}
function nextFocusIndex(position,count){return count===0?-1:Math.min(position,count-1)}
function restoreFeedFocus(selector,position){const items=[...document.querySelectorAll(selector+' [data-del]')],at=nextFocusIndex(position,items.length),el=at>=0?items[at]:document.querySelector(selector==='#personalActivity'?'[data-panel="you"] [data-tab="record"]':'#syncStatus');if(el&&typeof el.focus==='function')el.focus()}
function requestDelete(index,id,feed){const item=logs[index];if(!item)return;const what=item.type==='bounty'?(item.bountyTitle||'bounty'):`${CAT_LABELS[item.type]||item.type}${item.hardestGrade?' '+item.hardestGrade:''}`,buttons=[...document.querySelectorAll(feedSelector(feed)+' [data-del]')],position=Math.max(0,buttons.findIndex(el=>Number(el.dataset&&el.dataset.del)===index));pendingDelete={entry:item,index,id,feed,position,label:what};askConfirm('Delete this entry?',`Delete ${what} for ${item.name}?`,performDelete,'Delete',endpoint?'This cannot be undone.':'You can undo this from the bar that appears.')}
let crewFeedLimit=20,personalFeedLimit=5,feedType='all',crewFeedType='all';
function resetFeedLimits(){crewFeedLimit=20;personalFeedLimit=5}
function filterByType(items,type){return !type||type==='all'?items:items.filter(x=>x&&x.type===type)}
function feedChips(){return[{type:'all',icon:'',label:'All'},...CATEGORIES.map(t=>({type:t,icon:TYPE_ICONS[t]||'',label:CAT_LABELS[t]||t}))]}
function renderFeedChips(sel,active){const el=document.querySelector(sel);if(!el)return;el.innerHTML=feedChips().map(c=>`<button class="cat-chip" type="button" data-feed-type="${c.type}" aria-pressed="${c.type===active}">${c.icon?`<b aria-hidden="true">${c.icon}</b>`:''}${esc(c.label)}</button>`).join('')}
function setFeedType(type,crew){const next=type&&CATEGORIES.includes(type)?type:'all';if(next===(crew?crewFeedType:feedType))return;if(crew)crewFeedType=next;else feedType=next;resetFeedLimits();render()}
function showMoreFeed(feed){if(feed==='personal')personalFeedLimit=Math.min(personalFeedLimit+5,logs.length);else crewFeedLimit=Math.min(crewFeedLimit+20,logs.length);render()}
function renderShowMore(id,shown,total){const btn=document.querySelector(id);if(!btn)return;btn.classList.toggle('hide',shown>=total)}
let lastDeleted=null;
function undoDelete(){if(!lastDeleted||endpoint)return;const {entry,index}=lastDeleted;lastDeleted=null;logs=logs.slice(0,index).concat([entry],logs.slice(index));const stored=persistLocal();render();toast(stored?'Entry restored.':'Restored on this device only — storage is full.')}
function renderUndo(){if(endpoint)lastDeleted=null;const bar=document.querySelector('#undoBar');if(!bar)return;const show=Boolean(lastDeleted);bar.classList.toggle('hide',!show);const text=document.querySelector('#undoText');if(text)text.textContent=show?'Deleted '+lastDeleted.label+'.':''}
async function performDelete(){const pending=pendingDelete;if(!pending)return;pendingDelete=null;const {entry,id,feed,position}=pending;if(endpoint){try{const response=await fetchShared(endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'delete',id})}),result=await response.json();if(!response.ok||!result.ok)throw Error(result?.error?.message||'Delete rejected.');await loadRemote(true);toast('Entry deleted.')}catch(error){toast(`Delete failed — ${error.message}`)}}else{const at=logs.indexOf(entry);if(at>=0){lastDeleted={entry,index:at,label:pending.label||'entry'};logs=logs.filter(x=>x!==entry);persistLocal();render();toast('Entry deleted.')}}closeModal('confirmModal');restoreFeedFocus(feedSelector(feed),position)}
function addParticipantRow(person={name:''}){const el=document.querySelector('#participantRows'),index=el.children.length;el.insertAdjacentHTML('beforeend',`<div class="participant-row"><input aria-label="Participant ${index+1} name" class="participant-name" maxlength="30" placeholder="Name" value="${esc(person.name)}" /><button class="icon-btn remove-participant" type="button" aria-label="Remove ${esc(person.name||'participant')}">×</button></div>`)}
function populateSetup(){document.querySelector('#endpoint').value=endpoint;document.querySelector('#challengeStart').value=config.startDate;document.querySelector('#tripDate').value=config.tripDate;document.querySelector('#groupGoalInput').value=config.goal;const rows=document.querySelector('#participantRows');rows.innerHTML='';config.crew.forEach(addParticipantRow);if(!config.crew.length)addParticipantRow();document.querySelector('#scriptCode').textContent=SCRIPT}
function openSetup(){populateSetup();openModal('setupModal');document.querySelector('#endpoint').focus()}
function readSetupConfig(){const crew=[...document.querySelectorAll('.participant-row')].map(row=>({name:row.querySelector('.participant-name').value.trim()})).filter(x=>x.name);return{startDate:document.querySelector('#challengeStart').value,tripDate:document.querySelector('#tripDate').value,goal:Number(document.querySelector('#groupGoalInput').value),crew}}
function validateSetup(value){const parsed=parseRemoteConfig(value,[]),errors=Object.assign({},parsed.errors);if(!value.crew.length)errors.crew='Add at least one participant.';return{value:parsed.value,errors}}
async function testConnection(){const url=document.querySelector('#endpoint').value.trim(),result=document.querySelector('#testResult');result.textContent='Testing…';try{const response=await fetchShared(url),remote=unpackRemote(await response.json());result.textContent=`Connected — API v${remote.version}`;return true}catch(error){result.textContent=error.message==='version'?`Outdated Apps Script — deploy v${[...SUPPORTED_API_VERSIONS][0]}`:'Connection failed';return false}}
async function saveSetup(){const candidate=readSetupConfig(),check=validateSetup(candidate),errors=document.querySelector('#setupErrors'),url=document.querySelector('#endpoint').value.trim();if(Object.keys(check.errors).length){errors.textContent=Object.values(check.errors).join(' ');errors.classList.remove('hide');return}errors.classList.add('hide');const button=document.querySelector('#saveSetupBtn');button.disabled=true;button.textContent='Saving…';try{if(url){const response=await fetchShared(url,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action:'saveConfig',config:candidate})}),saved=await response.json();if(!response.ok||!saved.ok)throw Error(saved?.error?.message||'The Sheet rejected setup.');endpoint=url;writeStore('roadToSendEndpoint',endpoint);config=sanitizeConfig(saved.config,candidate);configErrors={};lastSyncedAt=Date.now();protocolVersion=[...SUPPORTED_API_VERSIONS][0];await loadRemote()}else{config=candidate;configErrors={};persistLocal();render()}closeModal('setupModal');const copied=await copyCrewLink();if(!participant(me))openIdentity(false);toast(url?(copied?'Shared setup saved. Crew link copied.':'Shared setup saved. Copy the crew link from setup.'):'Local setup saved.')}catch(error){errors.textContent=error.message||'Setup could not be saved.';errors.classList.remove('hide')}finally{button.disabled=false;button.textContent='Save centrally & copy crew link'}}
async function shareProgress(){const text=shareSummary(String(me).toLowerCase());if(!text)return false;const nav=typeof navigator==='undefined'?null:navigator;if(nav&&typeof nav.share==='function'){try{await nav.share({text});return true}catch(error){if(error&&error.name==='AbortError')return false}}return copyText(text,'Progress copied — paste it anywhere.')}
async function copyText(text,okMessage){try{const nav=typeof navigator==='undefined'?null:navigator;if(!nav||!nav.clipboard||!nav.clipboard.writeText)throw Error('no clipboard');await navigator.clipboard.writeText(String(text==null?'':text));toast(okMessage);return true}catch{toast('Copy failed — copy it manually.');return false}}
function publicUrl(){const url=new URL(location.href);url.hash='';url.searchParams.delete('sheet');return url.toString()}
function shareSummary(nameLower,today=challengeToday()){const key=String(nameLower==null?'':nameLower).trim().toLowerCase();if(!key)return'';const model=totalsModel(),i=model.sorted.findIndex(x=>x.name.toLowerCase()===key);if(i<0)return'';const row=model.sorted[i],prog=challengeProgress(today),lines=[`${row.name} · Road to Send`];if(prog)lines.push(`Day ${prog.day} of ${prog.totalDays}`);if(!row.total){lines.push('Just getting started — first points incoming.');lines.push(publicUrl());return lines.join('\n')}lines.push(`${row.total} pts · rank #${i+1}`);const spread=categoryBreakdown(key).rows.filter(r=>r.points>0).map(r=>`${r.icon} ${r.points}`).join('  ');if(spread)lines.push(spread);const streak=streakInfo(key,today);lines.push(`🔥 ${streak.current} day streak · best ${streak.best}`);const rec=personalRecords(key,today);if(rec.graded&&rec.hardest)lines.push(`Hardest send ${rec.hardest}`);lines.push(publicUrl());return lines.join('\n')}
async function copyCrewLink(){const url=new URL(publicUrl());if(endpoint)url.searchParams.set('sheet',endpoint);return copyText(url.toString(),'Crew link copied.')}
function copyScript(){copyText(SCRIPT,'Apps Script copied.')}
function exportData(){let url='';try{const blob=new Blob([JSON.stringify({version:[...SUPPORTED_API_VERSIONS][0],exportedAt:new Date().toISOString(),mode:endpoint?'shared-cache':'local',config,activities:logs},null,2)],{type:'application/json'}),a=document.createElement('a');url=URL.createObjectURL(blob);a.href=url;a.download=`road-to-send-${challengeToday()}.json`;a.click();toast('Export downloaded.')}catch{toast('Export failed — try a different browser.')}finally{if(url)URL.revokeObjectURL(url)}}
function disconnect(){askConfirm('Use local mode?','Switch this device to local mode? Shared Sheet data will remain untouched.',performDisconnect,'Use local mode','')}
function performDisconnect(){lastDeleted=null;resetFeedLimits();closeModal('confirmModal');localStorage.removeItem('roadToSendEndpoint');endpoint='';logs=sanitizeActivities(safeJson('roadToSendLogsV9',[],Array.isArray));config=sanitizeConfig(safeJson('roadToSendConfigV9',defaultConfig(),x=>x&&typeof x==='object'));syncState='local';configErrors={};closeModal('setupModal');setDefaultRecordDate();render();toast('Using local mode.')}
function init(){loadInitialState();document.querySelector('#hardestGrade').innerHTML='<option value="">Grade (optional)</option>'+GRADES.map(x=>`<option value="${x}">${x}</option>`).join('');setDefaultRecordDate();document.querySelectorAll('[data-tab]').forEach(x=>x.addEventListener('click',event=>{event.preventDefault();showTab(x.dataset.tab)}));document.querySelectorAll('input[name="activityType"]').forEach(x=>x.addEventListener('change',updateRecordPreview));document.querySelector('#hardestGrade').addEventListener('change',updateRecordPreview);const noteField=document.querySelector('#activityNote');if(noteField)noteField.addEventListener('input',updateRecordPreview);const bountySelect=document.querySelector('#bountySelect');if(bountySelect)bountySelect.addEventListener('change',updateRecordPreview);document.querySelector('#activityDate').addEventListener('change',updateRecordPreview);document.querySelector('#dateToggle').addEventListener('click',()=>{const box=document.querySelector('#dateFields'),toggle=document.querySelector('#dateToggle'),open=box.classList.toggle('hide')===false;toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'－ Use today instead':'＋ Different day';if(open)document.querySelector('#activityDate').focus();else{setDefaultRecordDate();updateRecordPreview()}});document.querySelector('#recordForm').addEventListener('submit',submitActivity);document.querySelector('#saveIdentity').addEventListener('click',saveIdentity);document.querySelector('#createProfile').addEventListener('click',createProfile);document.querySelector('#identityClose').addEventListener('click',()=>closeModal('identityModal'));const weekReviewClose=document.querySelector('#weekReviewClose');if(weekReviewClose)weekReviewClose.addEventListener('click',()=>closeModal('weekReviewModal'));const weekReviewCrewBtn=document.querySelector('#weekReviewCrewBtn');if(weekReviewCrewBtn)weekReviewCrewBtn.addEventListener('click',()=>{closeModal('weekReviewModal');showTab('crew')});document.querySelector('#saveProxy').addEventListener('click',saveProxy);const setLeaderMetric=v=>{if(leaderMetric===v)return;leaderMetric=v;render()},setLeaderScope=v=>{if(leaderScope===v)return;leaderScope=v;render()};document.querySelector('#leaderPointsBtn').addEventListener('click',()=>setLeaderMetric('points'));document.querySelector('#leaderBountyBtn').addEventListener('click',()=>setLeaderMetric('bounty'));document.querySelector('#leaderWeekBtn').addEventListener('click',()=>setLeaderScope('week'));document.querySelector('#leaderOverallBtn').addEventListener('click',()=>setLeaderScope('overall'));document.querySelector('#syncStatus').addEventListener('click',()=>loadRemote(true));document.querySelector('#diagnosticCode').addEventListener('click',()=>copyText(syncErrorCode,'Diagnostic code copied.'));const shareBtn=document.querySelector('#shareBtn');if(shareBtn)shareBtn.addEventListener('click',shareProgress);document.querySelector('#addParticipant').addEventListener('click',()=>addParticipantRow());document.querySelector('#participantRows').addEventListener('click',event=>{const button=event.target.closest('.remove-participant');if(button)button.closest('.participant-row').remove()});document.querySelector('#personalActivity').addEventListener('click',event=>{const button=event.target.closest('[data-del]');if(button)requestDelete(Number(button.dataset.del),button.dataset.id,'personal')});const feedFilter=document.querySelector('#feedFilter');if(feedFilter)feedFilter.addEventListener('click',event=>{const chip=event.target.closest('[data-feed-type]');if(chip)setFeedType(chip.dataset.feedType)});const crewFeedFilter=document.querySelector('#crewFeedFilter');if(crewFeedFilter)crewFeedFilter.addEventListener('click',event=>{const chip=event.target.closest('[data-feed-type]');if(chip)setFeedType(chip.dataset.feedType,true)});document.querySelector('#crew').addEventListener('click',event=>{const button=event.target.closest('[data-person]');if(button)openPersonCard(button.dataset.person)});document.querySelector('#personClose').addEventListener('click',()=>closeModal('personModal'));document.querySelector('#confirmOk').addEventListener('click',confirmProceed);document.querySelector('#confirmCancel').addEventListener('click',()=>closeModal('confirmModal'));const undoBtn=document.querySelector('#undoDelete');if(undoBtn)undoBtn.addEventListener('click',undoDelete);const undoX=document.querySelector('#undoDismiss');if(undoX)undoX.addEventListener('click',()=>{lastDeleted=null;renderUndo()});document.querySelector('#confirmClose').addEventListener('click',()=>closeModal('confirmModal'));const moreYou=document.querySelector('#personalShowMore');if(moreYou)moreYou.addEventListener('click',()=>showMoreFeed('personal'));const moreCrew=document.querySelector('#crewShowMore');if(moreCrew)moreCrew.addEventListener('click',()=>showMoreFeed('crew'));['identityModal','proxyModal','weekReviewModal','confirmModal','personModal','setupModal'].forEach(id=>{const m=document.querySelector('#'+id);if(m)m.addEventListener('click',event=>closeIfScrim(event,id))});document.querySelector('#todayBounties').addEventListener('click',event=>{const btn=event.target.closest('[data-claim-bounty]');if(btn)claimBounty(btn.dataset.claimBounty)});const weekToggle=document.querySelector('#bountyWeekToggle');if(weekToggle)weekToggle.addEventListener('click',toggleBountyWeek);const claimedTgl=document.querySelector('#claimedToggle');if(claimedTgl)claimedTgl.addEventListener('click',toggleClaimed);document.querySelector('#todayCategories').addEventListener('click',event=>{const chip=event.target.closest('[data-cat]');if(chip)prefillCategory(chip.dataset.cat)});document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.modal.open').forEach(x=>closeModal(x.id))});document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible')return;if(challengeToday()!==renderedDay)render();if(endpoint&&Date.now()-lastSyncedAt>300000)loadRemote()});const start=location.hash.slice(1);showTab(['you','record','crew'].includes(start)?start:'you');render();if(endpoint)loadRemote();else{if(!participant(me))openIdentity(false);maybeShowWeekReview()}}
if(typeof document!=='undefined')init();
